func LogAudit(db *sql.DB, actorId string, role string, action string, entityType string, entityId string, success bool, details map[string]interface{}) {
	auditId := uuid.New().String()
	if details == nil {
		details = make(map[string]interface{})
	}
	detailsJSON, _ := json.Marshal(details)
	_, _ = db.Exec(`
		INSERT INTO audit_trail (audit_id, actor_id, role, actor_role, action, entity_type, entity_id, success, occurred_at, details)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8, NOW(), $9)
	`, auditId, actorId, role, role, action, entityType, entityId, success, detailsJSON)
}

func LogTimeline(db *sql.DB, sampleId *string, journeyId *string, assignmentId *string, action string, actorId string, role string, entityType string, entityId string, success bool, details map[string]interface{}) {
	if details == nil {
		details = make(map[string]interface{})
	}
	detailsJSON, _ := json.Marshal(details)
	_, _ = db.Exec(`
		INSERT INTO timeline_entries (sample_id, journey_id, assignment_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, NOW(), $10)
	`, sampleId, journeyId, assignmentId, action, actorId, role, entityType, entityId, success, detailsJSON)
}

func SearchAuditTrail(db *sql.DB, query, actorId, entityType, entityId, action, role string, success *bool, fromTime, toTime *time.Time, limit, offset int, order string) (*models.AuditSearchResult, error) {
	if limit <= 0 {
		limit = 50
	}
	if limit > 200 {
		limit = 200
	}
	if offset < 0 {
		offset = 0
	}
	orderDir := "DESC"
	if strings.ToLower(order) == "asc" {
		orderDir = "ASC"
	}

	whereClauses := []string{"1=1"}
	var args []interface{}
	argIdx := 1

	if query != "" {
		whereClauses = append(whereClauses, fmt.Sprintf("(action ILIKE $%d OR entity_type ILIKE $%d OR role ILIKE $%d)", argIdx, argIdx, argIdx))
		args = append(args, "%"+query+"%")
		argIdx++
	}
	if actorId != "" {
		whereClauses = append(whereClauses, fmt.Sprintf("actor_id = $%d", argIdx))
		args = append(args, actorId)
		argIdx++
	}
	if entityType != "" {
		whereClauses = append(whereClauses, fmt.Sprintf("entity_type = $%d", argIdx))
		args = append(args, entityType)
		argIdx++
	}
	if entityId != "" {
		whereClauses = append(whereClauses, fmt.Sprintf("entity_id = $%d", argIdx))
		args = append(args, entityId)
		argIdx++
	}
	if action != "" {
		whereClauses = append(whereClauses, fmt.Sprintf("action = $%d", argIdx))
		args = append(args, action)
		argIdx++
	}
	if role != "" {
		whereClauses = append(whereClauses, fmt.Sprintf("role = $%d", argIdx))
		args = append(args, role)
		argIdx++
	}
	if success != nil {
		whereClauses = append(whereClauses, fmt.Sprintf("success = $%d", argIdx))
		args = append(args, *success)
		argIdx++
	}
	if fromTime != nil {
		whereClauses = append(whereClauses, fmt.Sprintf("occurred_at >= $%d", argIdx))
		args = append(args, *fromTime)
		argIdx++
	}
	if toTime != nil {
		whereClauses = append(whereClauses, fmt.Sprintf("occurred_at <= $%d", argIdx))
		args = append(args, *toTime)
		argIdx++
	}

	whereSQL := strings.Join(whereClauses, " AND ")

	var total int
	countQuery := fmt.Sprintf("SELECT COUNT(*) FROM audit_trail WHERE %s", whereSQL)
	err := db.QueryRow(countQuery, args...).Scan(&total)
	if err != nil {
		return nil, err
	}

	selectQuery := fmt.Sprintf(`
		SELECT audit_id, actor_id, role, actor_role, action, entity_type, entity_id, success, occurred_at, details
		FROM audit_trail
		WHERE %s
		ORDER BY occurred_at %s
		LIMIT $%d OFFSET $%d
	`, whereSQL, orderDir, argIdx, argIdx+1)

	args = append(args, limit, offset)
	rows, err := db.Query(selectQuery, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	entries := make([]models.AuditEntry, 0)
	for rows.Next() {
		var e models.AuditEntry
		var occurredAt time.Time
		var detailsJSON []byte

		if err := rows.Scan(&e.AuditId, &e.ActorId, &e.Role, &e.ActorRole, &e.Action, &e.EntityType, &e.EntityId, &e.Success, &occurredAt, &detailsJSON); err != nil {
			return nil, err
		}
		e.AuditIDAlt = e.AuditId
		e.ActorIDAlt = e.ActorId
		e.EntityIDAlt = e.EntityType
		e.EntityIDVal = e.EntityId
		e.OccurredAt = occurredAt.Format(time.RFC3339Nano)
		e.OccurredAtAlt = e.OccurredAt
		_ = json.Unmarshal(detailsJSON, &e.Details)
		entries = append(entries, e)
	}

	hasMore := offset+len(entries) < total
	var nextOffset *int
	if hasMore {
		no := offset + len(entries)
		nextOffset = &no
	}

	return &models.AuditSearchResult{
		Entries:    entries,
		Total:      total,
		Returned:   len(entries),
		Offset:     offset,
		Limit:      limit,
		Order:      strings.ToLower(orderDir),
		HasMore:    hasMore,
		NextOffset: nextOffset,
	}, nil
}

// WebSocket & Realtime Events

type Hub struct {
	clients map[*websocket.Conn]bool
	mu      sync.RWMutex
}

var GlobalHub = &Hub{
	clients: make(map[*websocket.Conn]bool),
}

func (h *Hub) Register(conn *websocket.Conn) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.clients[conn] = true
}

func (h *Hub) Unregister(conn *websocket.Conn) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if _, ok := h.clients[conn]; ok {
		delete(h.clients, conn)
		_ = conn.Close()
	}
}

func (h *Hub) Broadcast(event models.RealtimeEvent) {
	h.mu.RLock()
	defer h.mu.RUnlock()
	for client := range h.clients {
		_ = client.WriteJSON(event)
	}
}

func BroadcastRealtimeEvent(db *sql.DB, eventType, entityType, entityId string, payload map[string]interface{}) {
	if payload == nil {
		payload = make(map[string]interface{})
	}
	payloadJSON, _ := json.Marshal(payload)

	var id int64
	var createdAt time.Time
	err := db.QueryRow(`
		INSERT INTO realtime_events (type, entity_type, entity_id, payload, created_at)
		VALUES ($1, $2, $3, $4, NOW())
		RETURNING id, created_at
	`, eventType, entityType, entityId, payloadJSON).Scan(&id, &createdAt)

	if err == nil {
		event := models.RealtimeEvent{
			ID:         id,
			Type:       eventType,
			EntityType: entityType,
			EntityId:   entityId,
			Payload:    payload,
			CreatedAt:  createdAt.Format(time.RFC3339Nano),
		}
		GlobalHub.Broadcast(event)
	}
}

func GetRealtimeEventsSince(db *sql.DB, since int64) ([]models.RealtimeEvent, int64, error) {
	rows, err := db.Query(`
		SELECT id, type, entity_type, entity_id, payload, created_at
		FROM realtime_events
		WHERE id > $1
		ORDER BY id ASC
		LIMIT 100
	`, since)
	if err != nil {
		return nil, 0, err
	}
	defer rows.Close()

	var events []models.RealtimeEvent
	cursor := since
	for rows.Next() {
		var e models.RealtimeEvent
		var payloadJSON []byte
		var createdAt time.Time
		if err := rows.Scan(&e.ID, &e.Type, &e.EntityType, &e.EntityId, &payloadJSON, &createdAt); err != nil {
			return nil, 0, err
		}
		_ = json.Unmarshal(payloadJSON, &e.Payload)
		e.CreatedAt = createdAt.Format(time.RFC3339Nano)
		events = append(events, e)
		if e.ID > cursor {
			cursor = e.ID
		}
	}
	if events == nil {
		events = make([]models.RealtimeEvent, 0)
	}
	return events, cursor, nil
}
