func FindFairWorker(db *sql.DB, role string, qualification string, assignedLocId *string, excludedWorkerIds []string) (*models.User, error) {
	rows, err := db.Query(`
		SELECT user_id, username, full_name, email, phone, roles, active_role, qualifications, certifications, active, assigned_location_id, available, capacity_units
		FROM users
		WHERE active = true AND available = true
	`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var eligibleWorkers []models.User
	for rows.Next() {
		var u models.User
		var rolesJSON, qualsJSON, certsJSON []byte
		var activeRole, assignedLoc sql.NullString
		if err := rows.Scan(&u.UserId, &u.Username, &u.FullName, &u.Email, &u.Phone, &rolesJSON, &activeRole, &qualsJSON, &certsJSON, &u.Active, &assignedLoc, &u.Available, &u.CapacityUnits); err != nil {
			return nil, err
		}
		_ = json.Unmarshal(rolesJSON, &u.Roles)
		_ = json.Unmarshal(qualsJSON, &u.Qualifications)
		_ = json.Unmarshal(certsJSON, &u.Certifications)
		if assignedLoc.Valid {
			loc := assignedLoc.String
			u.AssignedLocationId = &loc
		}

		// Check role
		hasRole := false
		for _, r := range u.Roles {
			if r == role || (r == "administrator" && role == "dispatcher") {
				hasRole = true
				break
			}
		}
		if !hasRole {
			continue
		}

		// Check qualification for collection
		if role == "collection_professional" && qualification != "" {
			hasQual := false
			for _, q := range u.Qualifications {
				if q == qualification {
					hasQual = true
					break
				}
			}
			if !hasQual {
				for _, c := range u.Certifications {
					if c.Active && (c.Code == qualification || c.Code == "CERT-"+qualification) {
						hasQual = true
						break
					}
				}
			}
			if !hasQual {
				continue
			}
		}

		// Check assigned location for node or lab
		if (role == "node_handler" || role == "laboratory_team") && assignedLocId != nil {
			if u.AssignedLocationId == nil || *u.AssignedLocationId != *assignedLocId {
				continue
			}
		}

		// Check excluded
		excluded := false
		for _, ex := range excludedWorkerIds {
			if ex == u.UserId {
				excluded = true
				break
			}
		}
		if excluded {
			continue
		}

		eligibleWorkers = append(eligibleWorkers, u)
	}

	if len(eligibleWorkers) == 0 {
		return nil, nil
	}

	// Fair sorting: calculate active workload and total assignments for each
	type workerScore struct {
		user        models.User
		activeCount int
		totalCount  int
	}
	var scored []workerScore

	for _, w := range eligibleWorkers {
		var activeCount, totalCount int
		_ = db.QueryRow(`
			SELECT 
				COUNT(*) FILTER (WHERE status IN ('accepted', 'at_pickup', 'picked_up', 'in_transit', 'arrived', 'in_progress', 'offered')),
				COUNT(*)
			FROM assignments
			WHERE worker_id = $1
		`, w.UserId).Scan(&activeCount, &totalCount)

		scored = append(scored, workerScore{
			user:        w,
			activeCount: activeCount,
			totalCount:  totalCount,
		})
	}

	// Pick lowest activeCount, then lowest totalCount
	best := scored[0]
	for _, s := range scored[1:] {
		if s.activeCount < best.activeCount || (s.activeCount == best.activeCount && s.totalCount < best.totalCount) {
			best = s
		}
	}

	return &best.user, nil
}

type CreateCollectionRequestParams struct {
	RequesterId             string             `json:"requesterId"`
	Origin                  *models.Coordinate `json:"origin"`
