func IsLocationStale(t *time.Time) bool {
	if t == nil {
		return true
	}
	return time.Since(*t) > 15*time.Minute
}

func ReadOperationsState(db *sql.DB, filters map[string]interface{}) (*models.OperationsState, error) {
	// 1. Samples
	sampleRows, err := db.Query(`
		SELECT sample_id, status, request_id, origin_lat, origin_lng, delivery_deadline, current_holder_id, active_journey_id, latest_latitude, latest_longitude, location_recorded_at
		FROM samples
		ORDER BY created_at DESC
		LIMIT 100
	`)
	if err != nil {
		return nil, err
	}
	defer sampleRows.Close()

	var samples []models.OpsSample
	for sampleRows.Next() {
		var s models.OpsSample
		var reqId, holderId, journeyId sql.NullString
		var lat, lng, lLat, lLng sql.NullFloat64
		var ddl time.Time
		var locRecordedAt sql.NullTime

		if err := sampleRows.Scan(&s.SampleId, &s.Status, &reqId, &lat, &lng, &ddl, &holderId, &journeyId, &lLat, &lLng, &locRecordedAt); err != nil {
			return nil, err
		}
		s.SampleIDAlt = s.SampleId
		if reqId.Valid {
			s.RequestId = &reqId.String
		}
		if lat.Valid && lng.Valid {
			s.Origin = &models.Coordinate{Latitude: lat.Float64, Longitude: lng.Float64}
		}
		ddlStr := ddl.Format(time.RFC3339Nano)
		s.DeliveryDeadline = &ddlStr
		if holderId.Valid {
			s.CurrentHolderId = &holderId.String
		}
		if journeyId.Valid {
			s.ActiveJourneyId = &journeyId.String
		}
		if lLat.Valid && lLng.Valid {
			s.LatestLocation = &models.Coordinate{Latitude: lLat.Float64, Longitude: lLng.Float64}
		}
		if locRecordedAt.Valid {
			tStr := locRecordedAt.Time.Format(time.RFC3339Nano)
			s.LocationRecordedAt = &tStr
			s.LocationStale = IsLocationStale(&locRecordedAt.Time)
		} else {
			s.LocationStale = true
		}
		samples = append(samples, s)
	}
	if samples == nil {
		samples = make([]models.OpsSample, 0)
	}

	// 2. Workers
	workerRows, err := db.Query(`
		SELECT u.user_id, u.full_name, u.roles, u.available, u.capacity_units, u.latest_latitude, u.latest_longitude, u.location_recorded_at,
		       COUNT(a.assignment_id) FILTER (WHERE a.status IN ('accepted', 'at_pickup', 'picked_up', 'in_transit', 'arrived', 'in_progress')) AS active_assignments
		FROM users u
		LEFT JOIN assignments a ON u.user_id = a.worker_id
		WHERE u.active = true AND (u.roles::text ILIKE '%collection_professional%' OR u.roles::text ILIKE '%delivery_partner%' OR u.roles::text ILIKE '%node_handler%' OR u.roles::text ILIKE '%laboratory_team%')
		GROUP BY u.user_id
	`)
	if err != nil {
		return nil, err
	}
	defer workerRows.Close()

	var workers []models.OpsWorker
	minAssign := 999999
	maxAssign := 0

	for workerRows.Next() {
		var w models.OpsWorker
		var fullName sql.NullString
		var rolesJSON []byte
		var lLat, lLng sql.NullFloat64
		var locRecordedAt sql.NullTime
		var activeAssignments int

		if err := workerRows.Scan(&w.WorkerId, &fullName, &rolesJSON, &w.Available, &w.CapacityUnits, &lLat, &lLng, &locRecordedAt, &activeAssignments); err != nil {
			return nil, err
		}
		w.WorkerIDAlt = w.WorkerId
		if fullName.Valid {
			w.FullName = &fullName.String
		}
		_ = json.Unmarshal(rolesJSON, &w.Roles)
		if w.Available {
			w.Status = "available"
		} else {
			w.Status = "unavailable"
		}
		w.AssignmentCount = activeAssignments
		if activeAssignments < minAssign {
			minAssign = activeAssignments
		}
		if activeAssignments > maxAssign {
			maxAssign = activeAssignments
		}
		if lLat.Valid && lLng.Valid {
			coord := &models.Coordinate{Latitude: lLat.Float64, Longitude: lLng.Float64}
			w.LatestLocation = coord
			w.LatestLocationAlt = coord
		}
		if locRecordedAt.Valid {
			tStr := locRecordedAt.Time.Format(time.RFC3339Nano)
			w.LocationRecordedAt = &tStr
			w.LocationStale = IsLocationStale(&locRecordedAt.Time)
		} else {
			w.LocationStale = true
		}
		workers = append(workers, w)
	}
	if workers == nil {
		workers = make([]models.OpsWorker, 0)
	}

	spread := 0
	if len(workers) > 0 && maxAssign >= minAssign {
		spread = maxAssign - minAssign
	}

	// 3. Locations
	locRows, err := db.Query(`
		SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active, func_collection_point, func_transfer_point, func_hub, func_laboratory, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units, accepted_sample_type_ids
		FROM locations
		ORDER BY name ASC
	`)
	if err != nil {
		return nil, err
	}
	defer locRows.Close()

	var locations []models.OperationsLocation
	for locRows.Next() {
		var loc models.OperationsLocation
		var funcCP, funcTP, funcHub, funcLab bool
		var capUnits, resUnits, coolCapUnits, coolResUnits int
		var acceptedJSON []byte

		if err := locRows.Scan(&loc.LocationId, &loc.Name, &loc.Coordinate.Latitude, &loc.Coordinate.Longitude, &loc.CoverageKm, &loc.HandlingMinutes, &loc.Active, &funcCP, &funcTP, &funcHub, &funcLab, &capUnits, &resUnits, &coolCapUnits, &coolResUnits, &acceptedJSON); err != nil {
			return nil, err
		}
		loc.ID = loc.LocationId
		loc.Functions = models.LocationFunctionStates{
			CollectionPoint: &funcCP,
			TransferPoint:   &funcTP,
			Hub:             &funcHub,
			Laboratory:      &funcLab,
		}
		loc.Capacity = &models.Capacity{
			CapacityUnits:        capUnits,
			ReservedUnits:        resUnits,
			AvailableUnits:       capUnits - resUnits,
			CooledCapacityUnits:  coolCapUnits,
			CooledReservedUnits:  coolResUnits,
			CooledAvailableUnits: coolCapUnits - coolResUnits,
		}
		_ = json.Unmarshal(acceptedJSON, &loc.AcceptedSampleTypeIds)
		locations = append(locations, loc)
	}
	if locations == nil {
		locations = make([]models.OperationsLocation, 0)
	}

	// 4. Connections
	connRows, err := db.Query(`
		SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM connections
	`)
	if err != nil {
		return nil, err
	}
	defer connRows.Close()

	var connections []models.OperationsConnection
	for connRows.Next() {
		var c models.OperationsConnection
		var capUnits, resUnits, coolCapUnits, coolResUnits int
		if err := connRows.Scan(&c.ConnectionId, &c.FromLocationId, &c.ToLocationId, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active, &capUnits, &resUnits, &coolCapUnits, &coolResUnits); err != nil {
			return nil, err
		}
		c.ID = c.ConnectionId
		c.Capacity = &models.Capacity{
			CapacityUnits:        capUnits,
			ReservedUnits:        resUnits,
			AvailableUnits:       capUnits - resUnits,
			CooledCapacityUnits:  coolCapUnits,
			CooledReservedUnits:  coolResUnits,
			CooledAvailableUnits: coolCapUnits - coolResUnits,
		}
		connections = append(connections, c)
	}
	if connections == nil {
		connections = make([]models.OperationsConnection, 0)
	}

	// 5. Handoffs
	handoffRows, _ := db.Query(`
		SELECT handoff_id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, sender_confirmed, receiver_confirmed, status, initiated_at
		FROM handoffs
		ORDER BY initiated_at DESC
		LIMIT 50
	`)
	var handoffs []map[string]interface{}
	if handoffRows != nil {
		for handoffRows.Next() {
			var hid, sid, fa, ta, snd, rcv, st string
			var sc, rc bool
			var initAt time.Time
			if err := handoffRows.Scan(&hid, &sid, &fa, &ta, &snd, &rcv, &sc, &rc, &st, &initAt); err == nil {
				handoffs = append(handoffs, map[string]interface{}{
					"handoffId":         hid,
					"sampleId":          sid,
					"fromAssignmentId":  fa,
					"toAssignmentId":    ta,
					"senderId":          snd,
					"receiverId":        rcv,
					"senderConfirmed":   sc,
					"receiverConfirmed": rc,
					"status":            st,
					"initiatedAt":       initAt.Format(time.RFC3339Nano),
				})
			}
		}
		handoffRows.Close()
	}
	if handoffs == nil {
		handoffs = make([]map[string]interface{}, 0)
	}

	// 6. Exceptions
	exRows, _ := db.Query(`
		SELECT exception_id, sample_id, laboratory_id, recorder_id, reason, status, observed_at
		FROM lab_exceptions
		ORDER BY observed_at DESC
		LIMIT 50
	`)
	var exceptions []map[string]interface{}
	if exRows != nil {
		for exRows.Next() {
			var eid, sid, rec, reason, status string
			var labId sql.NullString
			var obsAt time.Time
			if err := exRows.Scan(&eid, &sid, &labId, &rec, &reason, &status, &obsAt); err == nil {
				exMap := map[string]interface{}{
					"exceptionId": eid,
					"sampleId":    sid,
					"recorderId":  rec,
					"reason":      reason,
					"status":      status,
					"observedAt":  obsAt.Format(time.RFC3339Nano),
				}
				if labId.Valid {
					exMap["laboratoryId"] = labId.String
				}
				exceptions = append(exceptions, exMap)
			}
		}
		exRows.Close()
	}
	if exceptions == nil {
		exceptions = make([]map[string]interface{}, 0)
	}

	// Ineligible assignments count
	var ineligibles int
	_ = db.QueryRow("SELECT COUNT(*) FROM assignments WHERE worker_id IS NULL AND status = 'offered'").Scan(&ineligibles)

	return &models.OperationsState{
		Samples:                   samples,
		Workers:                   workers,
		Locations:                 locations,
		Connections:               connections,
		Routes:                    make([]map[string]interface{}, 0),
		Handoffs:                  handoffs,
		Delays:                    make([]map[string]interface{}, 0),
		Exceptions:                exceptions,
		AssignmentCountSpread:     spread,
		IneligibleAssignmentCount: ineligibles,
	}, nil
}

func ReadSampleState(db *sql.DB, sampleId string) (*models.SampleState, error) {
	var s models.SampleState
	var reqTime, ddlTime, locRecTime sql.NullTime
	var incompJSON []byte
	var status string
	var activeJ, targetLab sql.NullString
	var lLat, lLng sql.NullFloat64

	err := db.QueryRow(`
		SELECT sample_id, request_id, requester_id, origin_lat, origin_lng, origin_type, requested_at, delivery_deadline, sample_type_id, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, serviceability, status, active_journey_id, target_laboratory_id, latest_latitude, latest_longitude, location_recorded_at
		FROM samples
		WHERE sample_id = $1
	`, sampleId).Scan(&s.SampleId, &s.RequestId, &s.RequesterId, &s.Origin.Latitude, &s.Origin.Longitude, &s.OriginType, &reqTime, &ddlTime, &s.SampleTypeId, &s.ContainerType, &s.TemperatureMinC, &s.TemperatureMaxC, &incompJSON, &s.Serviceability, &status, &activeJ, &targetLab, &lLat, &lLng, &locRecTime)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrNotFound
		}
		return nil, err
	}

	if reqTime.Valid {
		s.RequestedAt = reqTime.Time.Format(time.RFC3339Nano)
	}
	if ddlTime.Valid {
		s.DeliveryDeadline = ddlTime.Time.Format(time.RFC3339Nano)
	}
	_ = json.Unmarshal(incompJSON, &s.IncompatibleSampleTypes)
	if s.IncompatibleSampleTypes == nil {
		s.IncompatibleSampleTypes = make([]string, 0)
	}
	s.State.Status = status
	if activeJ.Valid {
		s.ActiveJourneyId = &activeJ.String
	}
	if targetLab.Valid {
		s.TargetLaboratoryId = &targetLab.String
	}
	if lLat.Valid && lLng.Valid {
		s.LatestLocation = &models.Coordinate{Latitude: lLat.Float64, Longitude: lLng.Float64}
	}
	if locRecTime.Valid {
		tStr := locRecTime.Time.Format(time.RFC3339Nano)
		s.LocationRecordedAt = &tStr
		s.LocationStale = IsLocationStale(&locRecTime.Time)
	} else {
		s.LocationStale = true
	}

	// Active assignments
	assignRows, _ := db.Query("SELECT assignment_id FROM assignments WHERE sample_id = $1 AND status NOT IN ('completed', 'cancelled', 'expired')", sampleId)
	if assignRows != nil {
		for assignRows.Next() {
			var aid string
			if err := assignRows.Scan(&aid); err == nil {
				s.ActiveAssignmentIds = append(s.ActiveAssignmentIds, aid)
			}
		}
		assignRows.Close()
	}
	if s.ActiveAssignmentIds == nil {
		s.ActiveAssignmentIds = make([]string, 0)
	}

	// Timeline
	timeline, _ := GetSampleTimeline(db, sampleId)
	s.Timeline = timeline

	return &s, nil
}

