func GetSampleTimeline(db *sql.DB, sampleId string) ([]models.TimelineEntry, error) {
	rows, err := db.Query(`
		SELECT event_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
		FROM timeline_entries
		WHERE sample_id = $1
		ORDER BY event_id ASC
	`, sampleId)
	if err != nil {
		return make([]models.TimelineEntry, 0), err
	}
	defer rows.Close()

	var entries []models.TimelineEntry
	for rows.Next() {
		var e models.TimelineEntry
		var occurredAt time.Time
		var detailsJSON []byte
		if err := rows.Scan(&e.EventId, &e.Action, &e.ActorId, &e.Role, &e.EntityType, &e.EntityId, &e.Success, &occurredAt, &detailsJSON); err != nil {
			return make([]models.TimelineEntry, 0), err
		}
		e.OccurredAt = occurredAt.Format(time.RFC3339Nano)
		_ = json.Unmarshal(detailsJSON, &e.Details)
		entries = append(entries, e)
	}
	if entries == nil {
		entries = make([]models.TimelineEntry, 0)
	}
	return entries, nil
}

func ListRoleWork(db *sql.DB, actor *models.User, role, statusFilter string) (*models.RoleWork, error) {
	work := &models.RoleWork{
		Pending:    make([]map[string]interface{}, 0),
		InProgress: make([]map[string]interface{}, 0),
		Completed:  make([]map[string]interface{}, 0),
	}

	if role == "requester" {
		rows, err := db.Query(`
			SELECT sample_id, request_id, requester_id, status, serviceability, requested_at, delivery_deadline, earliest_collection_at, latest_collection_at, active_journey_id, target_laboratory_id, current_holder_id, location_recorded_at
			FROM samples
			WHERE requester_id = $1
			ORDER BY created_at DESC
		`, actor.UserId)
		if err == nil && rows != nil {
			defer rows.Close()
			for rows.Next() {
				var s models.SampleWorkItem
				var reqId, holderId, journeyId, labId sql.NullString
				var reqT, ddlT, earnT, lateT, locRecT sql.NullTime
				if err := rows.Scan(&s.SampleId, &s.RequestId, &s.RequesterId, &s.Status, &s.Serviceability, &reqT, &ddlT, &earnT, &lateT, &journeyId, &labId, &holderId, &locRecT); err == nil {
					s.Kind = "sample"
					s.SampleIDAlt = s.SampleId
					if journeyId.Valid {
						s.JourneyId = journeyId.String
						s.ActiveJourneyId = journeyId.String
					}
					if labId.Valid {
						s.LaboratoryId = labId.String
					}
					if holderId.Valid {
						s.CurrentHolderId = holderId.String
					}
					if locRecT.Valid {
						tStr := locRecT.Time.Format(time.RFC3339Nano)
						s.LocationRecordedAt = tStr
						s.LocationStale = IsLocationStale(&locRecT.Time)
					} else {
						s.LocationStale = true
					}
					history, _ := GetSampleTimeline(db, s.SampleId)
					s.History = history

					sMap, _ := json.Marshal(s)
					var m map[string]interface{}
					_ = json.Unmarshal(sMap, &m)

					if s.Status == "requested" {
						work.Pending = append(work.Pending, m)
					} else if s.Status == "sealed" || s.Status == "in_transit" || s.Status == "at_hub" {
						work.InProgress = append(work.InProgress, m)
					} else {
						work.Completed = append(work.Completed, m)
					}
				}
			}
		}
		return work, nil
	}

	// For workers: fetch assignments
	assignRows, err := db.Query(`
		SELECT a.assignment_id, a.sample_id, a.kind, a.status, a.journey_id, a.from_location_id, a.to_location_id, a.node_id, a.laboratory_id, a.sequence, a.offer_expires_at
		FROM assignments a
		WHERE (a.worker_id = $1 OR (a.worker_id IS NULL AND a.status = 'offered'))
		ORDER BY a.created_at DESC
	`, actor.UserId)
	if err == nil && assignRows != nil {
		defer assignRows.Close()
		for assignRows.Next() {
			var item models.AssignmentWorkItem
			var fromLoc, toLoc, nodeLoc, labLoc, jId sql.NullString
			var offExp sql.NullTime
			if err := assignRows.Scan(&item.AssignmentId, &item.SampleId, &item.Kind, &item.Status, &jId, &fromLoc, &toLoc, &nodeLoc, &labLoc, &item.Sequence, &offExp); err == nil {
				item.AssignmentIDAlt = item.AssignmentId
				item.SampleIDAlt = item.SampleId
				if jId.Valid {
					item.JourneyId = jId.String
				}
				if fromLoc.Valid {
					item.FromLocationId = fromLoc.String
				}
				if toLoc.Valid {
					item.ToLocationId = toLoc.String
				}
				if nodeLoc.Valid {
					item.NodeId = nodeLoc.String
				}
				if labLoc.Valid {
					item.LaboratoryId = labLoc.String
				}
				if offExp.Valid {
					item.OfferExpiresAt = offExp.Time.Format(time.RFC3339Nano)
				}
				history, _ := GetSampleTimeline(db, item.SampleId)
				item.History = history

				iMap, _ := json.Marshal(item)
				var m map[string]interface{}
				_ = json.Unmarshal(iMap, &m)

				if item.Status == "offered" || item.Status == "pending" {
					work.Pending = append(work.Pending, m)
				} else if item.Status == "accepted" || item.Status == "at_pickup" || item.Status == "picked_up" || item.Status == "in_transit" || item.Status == "in_progress" || item.Status == "arrived" {
					work.InProgress = append(work.InProgress, m)
				} else {
					work.Completed = append(work.Completed, m)
				}
			}
		}
	}

	return work, nil
}

func ReportDisruption(db *sql.DB, actor *models.User, resourceType, resourceId, reason, occurredAt string) (string, []string, []string, string, error) {
	disruptionId := uuid.New().String()

	// Deactivate resource
	if resourceType == "location" || resourceType == "node" {
		_, _ = db.Exec("UPDATE locations SET active = false, updated_at = NOW() WHERE location_id = $1", resourceId)
	} else if resourceType == "connection" {
		_, _ = db.Exec("UPDATE connections SET active = false, updated_at = NOW() WHERE connection_id = $1", resourceId)
	} else if resourceType == "worker" {
		_, _ = db.Exec("UPDATE users SET available = false, updated_at = NOW() WHERE user_id = $1", resourceId)
	}

	// Find affected samples
	rows, _ := db.Query(`
		SELECT DISTINCT s.sample_id, s.active_journey_id
		FROM samples s
		JOIN journeys j ON s.active_journey_id = j.journey_id
		WHERE j.status = 'active'
	`)
	var affectedSampleIds []string
	var replacementPlanIds []string
	if rows != nil {
		for rows.Next() {
			var sid string
			var jid sql.NullString
			if err := rows.Scan(&sid, &jid); err == nil {
				affectedSampleIds = append(affectedSampleIds, sid)
				if jid.Valid {
					replacementPlanIds = append(replacementPlanIds, jid.String)
				}
			}
		}
		rows.Close()
	}

	affectedJSON, _ := json.Marshal(affectedSampleIds)
	replPlansJSON, _ := json.Marshal(replacementPlanIds)
	replanStatus := "replaced"
	if len(affectedSampleIds) == 0 {
		replanStatus = "not_required"
	}

	_, _ = db.Exec(`
		INSERT INTO disruptions (disruption_id, resource_type, resource_id, reason, occurred_at, affected_sample_ids, replacement_plan_ids, replan_status)
		VALUES ($1, $2, $3, $4, NOW(), $5, $6, $7)
	`, disruptionId, resourceType, resourceId, reason, affectedJSON, replPlansJSON, replanStatus)

	LogAudit(db, actor.UserId, actor.ActiveRole, "report_disruption", "disruption", disruptionId, true, map[string]interface{}{
		"resourceType": resourceType,
		"resourceId":   resourceId,
		"reason":       reason,
	})

	BroadcastRealtimeEvent(db, "network_disruption", "disruption", disruptionId, map[string]interface{}{
		"disruptionId": disruptionId,
		"resourceType": resourceType,
		"resourceId":   resourceId,
	})

	return disruptionId, affectedSampleIds, replacementPlanIds, replanStatus, nil
}

func CancelJourney(db *sql.DB, actor *models.User, journeyId string, expectedPlanVersion int, reason string) ([]string, error) {
	var j struct {
		JourneyId   string
		PlanVersion int
		Status      string
		SampleIds   []byte
	}
	err := db.QueryRow("SELECT journey_id, plan_version, status, sample_ids FROM journeys WHERE journey_id = $1", journeyId).Scan(&j.JourneyId, &j.PlanVersion, &j.Status, &j.SampleIds)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrNotFound
		}
		return nil, err
	}

	if expectedPlanVersion != 0 && j.PlanVersion != expectedPlanVersion {
		return nil, ErrStalePlan
	}

	var sampleIds []string
	_ = json.Unmarshal(j.SampleIds, &sampleIds)

	_, _ = db.Exec("UPDATE journeys SET status = 'cancelled', updated_at = NOW() WHERE journey_id = $1", journeyId)
	_, _ = db.Exec("UPDATE assignments SET status = 'cancelled', updated_at = NOW() WHERE journey_id = $1 AND status NOT IN ('completed')", journeyId)
	for _, sid := range sampleIds {
		_, _ = db.Exec("UPDATE samples SET status = 'cancelled', updated_at = NOW() WHERE sample_id = $1", sid)
	}

	LogAudit(db, actor.UserId, actor.ActiveRole, "cancel_journey", "journey", journeyId, true, map[string]interface{}{
		"reason": reason,
	})

	return sampleIds, nil
}
