func SearchAuditTrailHandler(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		user, err := GetAuthUser(r, db)
		if err != nil {
			SendError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
			return
		}
		if !auth.HasRole(user, "administrator", "dispatcher") {
			SendError(w, http.StatusForbidden, "forbidden", "Only dispatcher or administrator can search audit trail")
			return
		}

		var req struct {
			Query      string  `json:"query"`
			ActorId    string  `json:"actorId"`
			EntityType string  `json:"entityType"`
			EntityId   string  `json:"entityId"`
			Action     string  `json:"action"`
			Role       string  `json:"role"`
			Success    *bool   `json:"success"`
			FromTime   *string `json:"fromTime"`
			ToTime     *string `json:"toTime"`
			Limit      int     `json:"limit"`
			Offset     int     `json:"offset"`
			Order      string  `json:"order"`
		}
		_ = json.NewDecoder(r.Body).Decode(&req)

		var fromT, toT *time.Time
		if req.FromTime != nil {
			if t, err := time.Parse(time.RFC3339, *req.FromTime); err == nil {
				fromT = &t
			}
		}
		if req.ToTime != nil {
			if t, err := time.Parse(time.RFC3339, *req.ToTime); err == nil {
				toT = &t
			}
		}

		result, err := service.SearchAuditTrail(db, req.Query, req.ActorId, req.EntityType, req.EntityId, req.Action, req.Role, req.Success, fromT, toT, req.Limit, req.Offset, req.Order)
		if err != nil {
			SendError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}

		SendJSON(w, http.StatusOK, map[string]interface{}{
			"data": result,
		})
	}
