func ConfigureCapacityHandler(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		user, err := GetAuthUser(r, db)
		if err != nil {
			SendError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
			return
		}

		var req struct {
			ResourceId          string `json:"resourceId"`
			CapacityUnits       int    `json:"capacityUnits"`
			CooledCapacityUnits int    `json:"cooledCapacityUnits"`
		}
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			SendError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON")
			return
		}

		// Try updating location capacity first, then connection capacity
		res, err := db.Exec(`
			UPDATE locations
			SET capacity_units = $1, cooled_capacity_units = $2, updated_at = NOW()
			WHERE location_id = $3
		`, req.CapacityUnits, req.CooledCapacityUnits, req.ResourceId)
		if err == nil {
			if count, _ := res.RowsAffected(); count > 0 {
				SendJSON(w, http.StatusOK, map[string]interface{}{
					"data": map[string]interface{}{
						"resourceId":          req.ResourceId,
						"capacityUnits":       req.CapacityUnits,
						"cooledCapacityUnits": req.CooledCapacityUnits,
					},
				})
				return
			}
		}

		_, _ = db.Exec(`
			UPDATE connections
			SET capacity_units = $1, cooled_capacity_units = $2, updated_at = NOW()
			WHERE connection_id = $3
		`, req.CapacityUnits, req.CooledCapacityUnits, req.ResourceId)

		SendJSON(w, http.StatusOK, map[string]interface{}{
			"data": map[string]interface{}{
				"resourceId":          req.ResourceId,
				"capacityUnits":       req.CapacityUnits,
				"cooledCapacityUnits": req.CooledCapacityUnits,
			},
		})
	}
}

