{"file_text":"package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"strings"
	"syscall"

	"lab-transport/internal/db"
	"lab-transport/internal/handlers"
)

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	database, err := db.Connect()
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}
	defer database.Close()

	if err := db.Migrate(database); err != nil {
		log.Fatalf("Migration failed: %v", err)
	}

	if err := db.SeedDefaultData(database); err != nil {
		log.Printf("Default data seeding warning: %v", err)
	}

	if err := db.EnsureAdminUser(database); err != nil {
		log.Printf("Admin user ensure warning: %v", err)
	}

	mux := http.NewServeMux()

	// Readiness endpoint
	mux.HandleFunc("/ready", handlers.ReadyHandler(database))

	// API Routes (45 endpoints)
	mux.HandleFunc("/api/authenticate-user", handlers.AuthenticateUserHandler(database))
	mux.HandleFunc("/api/select-active-role", handlers.SelectActiveRoleHandler(database))
	mux.HandleFunc("/api/ui/bootstrap", handlers.UIBootstrapHandler(database))
	mux.HandleFunc("/api/events", handlers.EventsHandler(database))

	// Serviceability
	mux.HandleFunc("/api/check-serviceability", handlers.CheckServiceabilityHandler(database))
	mux.HandleFunc("/api/read-serviceability-snapshot", handlers.ReadServiceabilitySnapshotHandler(database))

	// Requests & Samples
	mux.HandleFunc("/api/create-collection-request", handlers.CreateCollectionRequestHandler(database))
	mux.HandleFunc("/api/ingest-presealed-sample", handlers.IngestPresealedSampleHandler(database))
	mux.HandleFunc("/api/collect-and-seal-sample", handlers.CollectAndSealSampleHandler(database))
	mux.HandleFunc("/api/record-handling-checkpoint", handlers.RecordHandlingCheckpointHandler(database))
	mux.HandleFunc("/api/confirm-laboratory-receipt", handlers.ConfirmLaboratoryReceiptHandler(database))
	mux.HandleFunc("/api/record-laboratory-exception", handlers.RecordLaboratoryExceptionHandler(database))

	// Custody & Handoff
	mux.HandleFunc("/api/initiate-handoff", handlers.InitiateHandoffHandler(database))
	mux.HandleFunc("/api/confirm-handoff", handlers.ConfirmHandoffHandler(database))

	// Assignments & Workers
	mux.HandleFunc("/api/accept-assignment", handlers.AcceptAssignmentHandler(database))
	mux.HandleFunc("/api/decline-assignment", handlers.DeclineAssignmentHandler(database))
	mux.HandleFunc("/api/record-worker-location", handlers.RecordWorkerLocationHandler(database))
	mux.HandleFunc("/api/update-assignment-progress", handlers.UpdateAssignmentProgressHandler(database))
	mux.HandleFunc("/api/list-role-work", handlers.ListRoleWorkHandler(database))

	// Journeys & Plans
	mux.HandleFunc("/api/read-journey-plan", handlers.ReadJourneyPlanHandler(database))
	mux.HandleFunc("/api/reroute-journey", handlers.RerouteJourneyHandler(database))
	mux.HandleFunc("/api/split-journey", handlers.SplitJourneyHandler(database))
	mux.HandleFunc("/api/merge-journeys", handlers.MergeJourneysHandler(database))
	mux.HandleFunc("/api/edit-active-plan", handlers.EditActivePlanHandler(database))
	mux.HandleFunc("/api/cancel-journey", handlers.CancelJourneyHandler(database))
	mux.HandleFunc("/api/report-disruption", handlers.ReportDisruptionHandler(database))

	// Operations & Lifecycle
	mux.HandleFunc("/api/read-operations-state", handlers.ReadOperationsStateHandler(database))
	mux.HandleFunc("/api/read-sample-lifecycle", handlers.ReadSampleLifecycleHandler(database))
	mux.HandleFunc("/api/read-sample-state/", handlers.ReadSampleStateHandler(database))
	mux.HandleFunc("/api/search-audit-trail", handlers.SearchAuditTrailHandler(database))

	// User & Access Management
	mux.HandleFunc("/api/create-user", handlers.CreateUserHandler(database))
	mux.HandleFunc("/api/read-user/", handlers.ReadUserHandler(database))
	mux.HandleFunc("/api/update-user-access", handlers.UpdateUserAccessHandler(database))
	mux.HandleFunc("/api/set-worker-availability", handlers.SetWorkerAvailabilityHandler(database))

	// Network & Locations Configuration
	mux.HandleFunc("/api/create-location", handlers.CreateLocationHandler(database))
	mux.HandleFunc("/api/update-location", handlers.UpdateLocationHandler(database))
	mux.HandleFunc("/api/set-location-status", handlers.SetLocationStatusHandler(database))
	mux.HandleFunc("/api/set-location-function-status", handlers.SetLocationFunctionStatusHandler(database))
	mux.HandleFunc("/api/create-connection", handlers.CreateConnectionHandler(database))
	mux.HandleFunc("/api/set-connection-status", handlers.SetConnectionStatusHandler(database))
	mux.HandleFunc("/api/configure-capacity", handlers.ConfigureCapacityHandler(database))
	mux.HandleFunc("/api/configure-laboratory-acceptance", handlers.ConfigureLaboratoryAcceptanceHandler(database))

	// Sample Types
	mux.HandleFunc("/api/create-sample-type", handlers.CreateSampleTypeHandler(database))
	mux.HandleFunc("/api/update-sample-type", handlers.UpdateSampleTypeHandler(database))

	// Serve Map Assets from /opt/arena/map-assets
	mapAssetDir := "/opt/arena/map-assets"
	if _, err := os.Stat(mapAssetDir); err == nil {
		fs := http.StripPrefix("/map-assets/", http.FileServer(http.Dir(mapAssetDir)))
		mux.Handle("/map-assets/", fs)
	}

	// Serve Frontend React Static Files with SPA fallback
	frontendDist := "/workspace/frontend/dist"
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if strings.HasPrefix(r.URL.Path, "/api") || strings.HasPrefix(r.URL.Path, "/map-assets") || r.URL.Path == "/ready" {
			http.NotFound(w, r)
			return
		}
		path := filepath.Join(frontendDist, filepath.Clean(r.URL.Path))
		if stat, err := os.Stat(path); err == nil && !stat.IsDir() {
			http.ServeFile(w, r, path)
			return
		}
		// Fallback to index.html for client-side routing
		indexPath := filepath.Join(frontendDist, "index.html")
		if _, err := os.Stat(indexPath); err == nil {
			http.ServeFile(w, r, indexPath)
			return
		}
		w.WriteHeader(http.StatusOK)
		w.Write([]byte("Lab Sample Pickup & Delivery System API Running"))
	})

	// Wrap with CORS & Logging middleware
	handler := corsMiddleware(mux)

	server := &http.Server{
		Addr:    ":" + port,
		Handler: handler,
	}

	go func() {
		log.Printf("Server listening on http://127.0.0.1:%s", port)
		if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("Server ListenAndServe error: %v", err)
		}
	}()

	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
	<-quit
	log.Println("Shutting down server...")
}

func corsMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization, X-Requested-With, Sec-WebSocket-Protocol")

		if r.Method == "OPTIONS" {
			w.WriteHeader(http.StatusOK)
			return
		}

		next.ServeHTTP(w, r)
	})
}
