{"path":"/workspace/frontend/src/components/MapComponent.tsx","summary":"Create MapComponent with MapLibre & PMTiles","file_text":"import React, { useEffect, useRef } from 'react';
import maplibregl from 'maplibre-gl';
import * as pmtiles from 'pmtiles';
import { LocationItem, WorkerItem, SampleItem } from '../api';

interface MapComponentProps {
  locations?: LocationItem[];
  workers?: WorkerItem[];
  samples?: SampleItem[];
  selectedSample?: SampleItem | null;
  onSelectLocation?: (loc: LocationItem) => void;
  onSelectSample?: (sample: SampleItem) => void;
  center?: [number, number]; // [lng, lat]
  zoom?: number;
}

let protocolAdded = false;

export const MapComponent: React.FC<MapComponentProps> = ({
  locations = [],
  workers = [],
  samples = [],
  selectedSample,
  onSelectLocation,
  onSelectSample,
  center = [77.5946, 12.9716],
  zoom = 11,
}) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const markersRef = useRef<maplibregl.Marker[]>([]);

  useEffect(() => {
    if (!protocolAdded) {
      const protocol = new pmtiles.Protocol();
      maplibregl.addProtocol('pmtiles', protocol.tile);
      protocolAdded = true;
    }

    if (!mapContainerRef.current) return;

    const map = new maplibregl.Map({
      container: mapContainerRef.current,
      style: '/map-assets/style.json',
      center: center,
      zoom: zoom,
    });

    map.addControl(new maplibregl.NavigationControl(), 'top-right');
    mapRef.current = map;

    return () => {
      markersRef.current.forEach((m) => m.remove());
      markersRef.current = [];
      map.remove();
      mapRef.current = null;
    };
  }, []);

  // Update Markers
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;

    // Clear old markers
    markersRef.current.forEach((m) => m.remove());
    markersRef.current = [];

    // Render Locations (Nodes & Labs)
    locations.forEach((loc) => {
      if (!loc.coordinate || !loc.coordinate.latitude || !loc.coordinate.longitude) return;

      const el = document.createElement('div');
      const isLab = loc.type === 'laboratory' || (loc.functions && loc.functions['laboratory']);
      el.className = `flex items-center justify-center rounded-full text-white font-bold text-xs shadow-lg cursor-pointer transform hover:scale-110 transition duration-150 ${
        isLab ? 'bg-purple-600 w-8 h-8 border-2 border-white' : 'bg-blue-600 w-7 h-7 border-2 border-white'
      }`;
      el.innerHTML = isLab ? 'LAB' : 'HUB';

      const popup = new maplibregl.Popup({ offset: 25 }).setHTML(`
        <div class="p-2 text-gray-800 text-sm">
          <div class="font-bold text-base mb-1">${loc.name} (${loc.code})</div>
          <div class="text-xs text-gray-500 mb-1">Type: <span class="capitalize font-semibold">${loc.type}</span></div>
          <div class="text-xs">Regular Cap: ${loc.regularCapacity - (loc.regularReserved || 0)} / ${loc.regularCapacity} avail</div>
          <div class="text-xs">Cooled Cap: ${loc.cooledCapacity - (loc.cooledReserved || 0)} / ${loc.cooledCapacity} avail</div>
          ${loc.address ? `<div class="text-xs text-gray-600 mt-1">${loc.address}</div>` : ''}
        </div>
      `);

      el.addEventListener('click', () => {
        if (onSelectLocation) onSelectLocation(loc);
      });

      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([loc.coordinate.longitude, loc.coordinate.latitude])
        .setPopup(popup)
        .addTo(map);

      markersRef.current.push(marker);
    });

    // Render Workers
    workers.forEach((worker) => {
      if (!worker.latestLatitude || !worker.latestLongitude) return;

      const el = document.createElement('div');
      el.className = 'w-6 h-6 rounded-full bg-emerald-500 border-2 border-white shadow-md flex items-center justify-center text-white text-[10px] font-bold';
      el.innerHTML = 'W';

      const popup = new maplibregl.Popup({ offset: 20 }).setHTML(`
        <div class="p-2 text-gray-800 text-sm">
          <div class="font-bold">${worker.fullName || worker.username}</div>
          <div class="text-xs text-gray-500">Roles: ${(worker.roles || []).join(', ')}</div>
          <div class="text-xs">Workload: ${worker.workload || 0} items</div>
        </div>
      `);

      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([worker.latestLongitude, worker.latestLatitude])
        .setPopup(popup)
        .addTo(map);

      markersRef.current.push(marker);
    });

    // Render Samples (if not in a static node)
    samples.forEach((sample) => {
      const lat = sample.latestLatitude || (sample.origin && sample.origin.coordinate?.latitude);
      const lng = sample.latestLongitude || (sample.origin && sample.origin.coordinate?.longitude);
      if (!lat || !lng) return;

      const isEx = sample.isException;
      const el = document.createElement('div');
      el.className = `w-5 h-5 rounded-full border-2 border-white shadow flex items-center justify-center text-white text-[9px] font-bold cursor-pointer ${
        isEx ? 'bg-red-600 animate-pulse' : sample.status === 'received' ? 'bg-gray-400' : 'bg-amber-500'
      }`;
      el.innerHTML = 'S';

      const popup = new maplibregl.Popup({ offset: 15 }).setHTML(`
        <div class="p-2 text-gray-800 text-sm">
          <div class="font-bold">Sample: ${sample.sampleId.slice(0, 8)}...</div>
          <div class="text-xs">Type: <b>${sample.sampleType}</b> | Status: <b>${sample.status}</b></div>
          ${sample.isException ? `<div class="text-xs text-red-600 font-bold mt-1">Exception: ${sample.exceptionReason || 'Handling error'}</div>` : ''}
          <div class="text-xs text-gray-500 mt-1">Deadline: ${new Date(sample.deliveryDeadline).toLocaleTimeString()}</div>
        </div>
      `);

      el.addEventListener('click', () => {
        if (onSelectSample) onSelectSample(sample);
      });

      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([lng, lat])
        .setPopup(popup)
        .addTo(map);

      markersRef.current.push(marker);
    });

  }, [locations, workers, samples, onSelectLocation, onSelectSample]);

  // Center on selected sample if available
  useEffect(() => {
    if (!selectedSample || !mapRef.current) return;
    const lat = selectedSample.latestLatitude || (selectedSample.origin && selectedSample.origin.coordinate?.latitude);
    const lng = selectedSample.latestLongitude || (selectedSample.origin && selectedSample.origin.coordinate?.longitude);
    if (lat && lng) {
      mapRef.current.flyTo({ center: [lng, lat], zoom: 13 });
    }
  }, [selectedSample]);

  return (
    <div className="relative w-full h-full min-h-[400px] rounded-lg overflow-hidden border border-gray-200 shadow-inner">
      <div ref={mapContainerRef} className="absolute inset-0" />
      <div className="absolute bottom-2 left-2 bg-white/90 backdrop-blur px-3 py-1.5 rounded text-xs text-gray-700 shadow flex items-center space-x-3 z-10">
        <span className="flex items-center"><span className="w-2.5 h-2.5 rounded-full bg-blue-600 inline-block mr-1"></span> Hub</span>
        <span className="flex items-center"><span className="w-2.5 h-2.5 rounded-full bg-purple-600 inline-block mr-1"></span> Lab</span>
        <span className="flex items-center"><span className="w-2.5 h-2.5 rounded-full bg-emerald-500 inline-block mr-1"></span> Worker</span>
        <span className="flex items-center"><span className="w-2.5 h-2.5 rounded-full bg-amber-500 inline-block mr-1"></span> Sample</span>
        <span className="flex items-center"><span className="w-2.5 h-2.5 rounded-full bg-red-600 inline-block mr-1"></span> Exception</span>
      </div>
    </div>
  );
};
