{"file_text":"import React from 'react';
import { User, api } from '../api';
import { LogOut, User as UserIcon, Shield, RefreshCw } from 'lucide-react';

interface NavbarProps {
  user: User;
  onUserUpdate: (user: User) => void;
  onSignOut: () => void;
  activeTab: string;
  setActiveTab: (tab: string) => void;
}

export const Navbar: React.FC<NavbarProps> = ({
  user,
  onUserUpdate,
  onSignOut,
  activeTab,
  setActiveTab,
}) => {
  const [switching, setSwitching] = React.useState(false);

  const handleRoleChange = async (e: React.ChangeEvent<HTMLSelectElement>) => {
    const newRole = e.target.value;
    if (newRole === user.activeRole) return;
    try {
      setSwitching(true);
      const res = await api.selectActiveRole(newRole);
      localStorage.setItem('active_role', res.activeRole);
      onUserUpdate({ ...user, activeRole: res.activeRole });
    } catch (err: any) {
      alert(`Failed to switch role: ${err.message}`);
    } finally {
      setSwitching(false);
    }
  };

  const isOpsRole = user.activeRole === 'dispatcher' || user.activeRole === 'administrator' || user.activeRole === 'admin';
  const isAdmin = user.activeRole === 'administrator' || user.activeRole === 'admin';

  return (
    <header className="bg-slate-900 text-white shadow-md sticky top-0 z-30">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          {/* Logo / Brand */}
          <div className="flex items-center space-x-3">
            <div className="w-9 h-9 rounded-lg bg-indigo-600 flex items-center justify-center font-bold text-lg text-white shadow-md">
              🧪
            </div>
            <div>
              <span className="font-bold text-lg tracking-tight">LabTransport</span>
              <span className="text-xs text-indigo-400 block -mt-1 font-medium">Sample Logistics Network</span>
            </div>
          </div>

          {/* Navigation Tabs */}
          <nav className="flex space-x-1 sm:space-x-4">
            <button
              onClick={() => setActiveTab('work')}
              className={`px-3 py-1.5 rounded-md text-sm font-medium transition ${
                activeTab === 'work' ? 'bg-indigo-700 text-white shadow' : 'text-slate-300 hover:text-white hover:bg-slate-800'
              }`}
            >
              My Work
            </button>

            {isOpsRole && (
              <button
                onClick={() => setActiveTab('monitor')}
                className={`px-3 py-1.5 rounded-md text-sm font-medium transition ${
                  activeTab === 'monitor' ? 'bg-indigo-700 text-white shadow' : 'text-slate-300 hover:text-white hover:bg-slate-800'
                }`}
              >
                Operations Monitor
              </button>
            )}

            {isOpsRole && (
              <button
                onClick={() => setActiveTab('audit')}
                className={`px-3 py-1.5 rounded-md text-sm font-medium transition ${
                  activeTab === 'audit' ? 'bg-indigo-700 text-white shadow' : 'text-slate-300 hover:text-white hover:bg-slate-800'
                }`}
              >
                Audit History
              </button>
            )}

            {isAdmin && (
              <button
                onClick={() => setActiveTab('admin')}
                className={`px-3 py-1.5 rounded-md text-sm font-medium transition ${
                  activeTab === 'admin' ? 'bg-indigo-700 text-white shadow' : 'text-slate-300 hover:text-white hover:bg-slate-800'
                }`}
              >
                Admin Config
              </button>
            )}
          </nav>

          {/* User & Role Switcher */}
          <div className="flex items-center space-x-4">
            <div className="flex items-center space-x-2 bg-slate-800 px-3 py-1.5 rounded-lg border border-slate-700">
              <Shield className="w-4 h-4 text-indigo-400" />
              <label htmlFor="role-select" className="text-xs text-slate-400 font-medium">Role:</label>
              <select
                id="role-select"
                aria-label="Select Role"
                value={user.activeRole || ''}
                onChange={handleRoleChange}
                disabled={switching}
                className="bg-slate-900 text-xs font-semibold text-white px-2 py-1 rounded border border-slate-600 focus:outline-none focus:ring-1 focus:ring-indigo-500"
              >
                {user.roles && user.roles.map((r) => (
                  <option key={r} value={r}>
                    {r}
                  </option>
                ))}
              </select>
              {switching && <RefreshCw className="w-3.5 h-3.5 text-indigo-400 animate-spin" />}
            </div>

            <div className="hidden md:flex flex-col text-right">
              <span className="text-sm font-semibold text-white">{user.fullName || user.username}</span>
              <span className="text-[11px] text-slate-400">@{user.username}</span>
            </div>

            <button
              onClick={onSignOut}
              className="flex items-center space-x-1 text-slate-300 hover:text-red-400 p-2 rounded-lg hover:bg-slate-800 transition text-sm"
              title="Sign Out"
              aria-label="Sign Out"
            >
              <LogOut className="w-4 h-4" />
              <span className="hidden sm:inline">Sign Out</span>
            </button>
          </div>
        </div>
      </div>
    </header>
  );
};
