                      <td className="px-4 py-3 font-semibold text-slate-900">{n.name}</td>
                      <td className="px-4 py-3 font-mono">{n.code}</td>
                      <td className="px-4 py-3">{n.coordinate?.latitude.toFixed(4)}, {n.coordinate?.longitude.toFixed(4)}</td>
                      <td className="px-4 py-3">
