                      <td className="px-4 py-3">{r.cooledCapacity - (r.cooledReserved || 0)} / {r.cooledCapacity}</td>
                      <td className="px-4 py-3">
                        <span className={`px-2 py-0.5 rounded-full font-bold uppercase text-[10px] ${
                          r.status === 'active' ? 'bg-emerald-100 text-emerald-800' : 'bg-red-100 text-red-800'
                        }`}>
                          {r.status}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* EXCEPTIONS TABLE */}
          {activeCategory === 'exceptions' && (
            <div className="overflow-x-auto">
              {exceptions.length === 0 ? (
                <div className="text-xs text-slate-400 py-6 text-center italic">
                  No active exceptions in the transport network.
                </div>
              ) : (
                <table className="w-full text-left text-xs text-slate-700">
                  <thead className="bg-red-50 text-red-900 uppercase font-semibold border-b border-red-200">
                    <tr>
                      <th className="px-4 py-2.5">Sample ID</th>
                      <th className="px-4 py-2.5">Type</th>
                      <th className="px-4 py-2.5">Exception Reason</th>
                      <th className="px-4 py-2.5">Current Holder</th>
                      <th className="px-4 py-2.5">Deadline</th>
                      <th className="px-4 py-2.5 text-right">Action</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {exceptions.map((ex) => (
                      <tr key={ex.sampleId} className="hover:bg-red-50/40 transition">
                        <td className="px-4 py-3 font-mono font-semibold text-red-900">{ex.sampleId.slice(0, 8)}...</td>
                        <td className="px-4 py-3 font-semibold">{ex.sampleType}</td>
