{"file_text":"import React, { useState, useEffect } from 'react';
import { api, User } from './api';
import { Navbar } from './components/Navbar';
import { LoginView } from './components/LoginView';
import { RequesterView } from './components/RequesterView';
import { WorkerView } from './components/WorkerView';
import { MonitorDashboard } from './components/MonitorDashboard';
import { AuditView } from './components/AuditView';
import { AdminConfigView } from './components/AdminConfigView';
import { SampleDetailModal } from './components/SampleDetailModal';
import { RefreshCw } from 'lucide-react';

export function App() {
  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(() => localStorage.getItem('auth_token'));
  const [loading, setLoading] = useState<boolean>(true);
  const [activeTab, setActiveTab] = useState<string>('work');
  const [selectedSampleId, setSelectedSampleId] = useState<string | null>(null);

  const initSession = async () => {
    const savedToken = localStorage.getItem('auth_token');
    if (!savedToken) {
      setLoading(false);
      return;
    }
    try {
      const boot = await api.getUIBootstrap();
      setUser(boot.user);
    } catch (err) {
      console.warn('Session expired or invalid:', err);
      handleSignOut();
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    initSession();
  }, [token]);

  const handleLoginSuccess = (newToken: string, loggedInUser: User) => {
    setToken(newToken);
    setUser(loggedInUser);
    setActiveTab('work');
  };

  const handleSignOut = () => {
    localStorage.removeItem('auth_token');
    localStorage.removeItem('active_role');
    setToken(null);
    setUser(null);
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center text-white text-sm">
        <RefreshCw className="w-6 h-6 animate-spin mr-3 text-indigo-500" />
        <span>Initializing session...</span>
      </div>
    );
  }

  if (!user || !token) {
    return <LoginView onLoginSuccess={handleLoginSuccess} />;
  }

  const isRequester = user.activeRole === 'requester';
  const isOpsRole = user.activeRole === 'dispatcher' || user.activeRole === 'administrator' || user.activeRole === 'admin';
  const isAdmin = user.activeRole === 'administrator' || user.activeRole === 'admin';

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col font-sans">
      {/* Navbar with Role Switcher & Sign Out */}
      <Navbar
        user={user}
        onUserUpdate={setUser}
        onSignOut={handleSignOut}
        activeTab={activeTab}
        setActiveTab={setActiveTab}
      />

      {/* Main Container */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Work Tab */}
        {activeTab === 'work' && (
          <div>
            {isRequester ? (
              <RequesterView
                user={user}
                onSelectSample={(sampleId) => setSelectedSampleId(sampleId)}
              />
            ) : (
              <WorkerView
                user={user}
                onSelectSample={(sampleId) => setSelectedSampleId(sampleId)}
              />
            )}
          </div>
        )}

        {/* Monitor Tab */}
        {activeTab === 'monitor' && isOpsRole && (
          <MonitorDashboard
            onSelectSample={(sampleId) => setSelectedSampleId(sampleId)}
          />
        )}

        {/* Audit Tab */}
        {activeTab === 'audit' && isOpsRole && (
          <AuditView />
        )}

        {/* Admin Tab */}
        {activeTab === 'admin' && isAdmin && (
          <AdminConfigView />
        )}

      </main>

      {/* Global Sample Details & Lifecycle Modal */}
      {selectedSampleId && (
        <SampleDetailModal
          sampleId={selectedSampleId}
          currentUser={user}
          onClose={() => setSelectedSampleId(null)}
        />
      )}
    </div>
  );
}
export default App;
